from pathlib import Path
import tomllib


def tokens(path="tokens.txt"):
    return [line.strip() for line in Path(path).read_text().splitlines() if line.strip()]


def load(path="replica.toml"):
    settings = tomllib.loads(Path(path).read_text())
    policy = settings["policy"]

    # Continue accepting the original one-policy configuration, while allowing
    # operation-specific policies for catalog reads and session writes.
    if isinstance(policy, str):
        policies = {"default": policy}
    elif isinstance(policy, dict):
        required = {"catalog_reads", "session_writes"}
        missing = required.difference(policy)
        if missing:
            raise SystemExit(f"missing policy: {', '.join(sorted(missing))}")
        policies = {name: policy[name] for name in required}
    else:
        raise SystemExit("invalid policy")

    valid = set(tokens())
    if any(value not in valid for value in policies.values()):
        raise SystemExit("unknown policy")
    return settings
